args.command:
python3 -c "import pandas as pd; from pypdf import PdfReader; import re; vendors_df = pd.read_excel('/root/vendors.xlsx'); pos_df = pd.read_csv('/root/purchase_orders.csv'); vendors_map = dict(zip(vendors_df['name'], vendors_df['id'])); pos_map = pos_df.set_index('po_number').to_dict('index'); reader = PdfReader('/root/invoices.pdf'); 
for i, page in enumerate(reader.pages):
    text = page.extract_text()
    v_match = re.search(r'From:\s*(.*)', text)
    a_match = re.search(r'Total \$(.*)', text)
    p_match = re.search(r'PO Number:\s*(.*)', text)
    if v_match and a_match and p_match:
        v_name = v_match.group(1).strip()
        v_id = vendors_map.get(v_name)
        po = p_match.group(1).strip()
        amount = float(a_match.group(1).strip())
        if v_id and po in pos_map:
            po_data = pos_map[po]
            if abs(amount - po_data['amount']) <= 0.01 and po_data['vendor_id'] != v_id:
                print(f'Page {i+1}: Vendor Mismatch!')
"
